import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:habit_tracker/emoji.dart';
import 'package:habit_tracker/icon_picker.dart';
import 'package:habit_tracker/icons.dart';
import 'package:habit_tracker/store.dart';

void main() {
  group('the emoji set', () {
    test('is the whole of Unicode\'s, in its own groups', () {
      // Generated by tool/gen_emoji.py — a short list here means the generator
      // silently dropped most of the file.
      expect(emojiGroups, hasLength(greaterThanOrEqualTo(8)));
      expect(emojiGroups.values.fold(0, (n, g) => n + g.length),
          greaterThan(1500));
      expect(emojiGroups.keys, contains('Smileys & Emotion'));
    });

    test('the default emoji is one anyone can also pick', () {
      expect(emojiGroups.values.any((g) => g.containsKey(defaultEmoji)), isTrue);
    });

    test('every glyph carries the name search matches on', () {
      for (final group in emojiGroups.entries) {
        for (final e in group.value.entries) {
          expect(e.key, isNotEmpty, reason: '${group.key} has an empty glyph');
          expect(e.value.trim(), isNotEmpty,
              reason: '${e.key} in ${group.key} has no name');
          // Unicode names carry caps ('OK hand', 'flag: Japan'), so the
          // search lowercases both sides rather than trusting the data.
          expect(e.value, isNot(startsWith(' ')));
        }
      }
    });
  });

  group('the catalogue', () {
    test('has the reference\'s six groups and no empty one', () {
      expect(iconGroups, hasLength(6));
      for (final g in iconGroups.entries) {
        expect(g.value, isNotEmpty, reason: '${g.key} is empty');
      }
    });

    test('keys are unique across every group', () {
      final counted =
          iconGroups.values.fold(0, (n, g) => n + g.length);
      expect(iconByKey, hasLength(counted),
          reason: 'two groups share a key, so one icon is unreachable');
    });

    test('every key is lookup-safe and every group is indexed', () {
      for (final key in iconByKey.keys) {
        expect(iconFor(key), iconByKey[key]);
        expect(groupOfIcon, contains(key));
      }
    });

    test('the default is a real icon', () {
      expect(iconByKey, contains(defaultIcon));
    });

    test('an unknown key falls back rather than throwing', () {
      // A stored icon can outlive a rename; a habit whose icon vanished must
      // still draw something.
      expect(iconFor('no-such-icon'), iconByKey[defaultIcon]);
      expect(iconFor(''), iconByKey[defaultIcon]);
    });

    test('keys are stable-looking — lowercase, no spaces', () {
      for (final key in iconByKey.keys) {
        expect(key, matches(RegExp(r'^[a-z0-9-]+$')),
            reason: '"$key" will be awkward to search for or migrate');
      }
    });
  });

  group('icons and emoji are alternatives', () {
    test('a new habit gets an icon and no emoji', () {
      final h = Habit(id: 'x', name: 'h');
      expect(h.icon, defaultIcon);
      expect(h.emoji, '');
    });

    test('a habit saved before icons existed keeps its emoji', () {
      // Exactly what the previous version wrote.
      final legacy = Habit.fromJson({
        'id': '1',
        'name': 'Read',
        'emoji': '📖',
        'log': <String, int>{},
      });
      expect(legacy.emoji, '📖');
      expect(legacy.icon, '',
          reason: 'an old habit must not silently acquire an icon');
    });

    test('a habit saved with neither takes the default icon', () {
      final bare = Habit.fromJson({'id': '1', 'name': 'Read'});
      expect(bare.icon, defaultIcon);
    });

    test('both survive a save and reload', () {
      for (final h in [
        Habit(id: 'a', name: 'icon', icon: 'coffee', emoji: ''),
        Habit(id: 'b', name: 'emoji', icon: '', emoji: '🔥'),
      ]) {
        final back = Habit.fromJson(h.toJson());
        expect(back.icon, h.icon);
        expect(back.emoji, h.emoji);
      }
    });

    test('picking one clears the other', () {
      expect(const IconChoice.icon('coffee').emoji, '');
      expect(const IconChoice.emoji('🔥').icon, '');
    });
  });

  group('the picker', () {
    testWidgets('opens on Icon, and Emoji switches the grid', (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: TextButton(
              onPressed: () =>
                  showIconPicker(context, icon: defaultIcon, emoji: ''),
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();

      expect(find.text('Icon'), findsOneWidget);
      expect(find.text('Emoji'), findsOneWidget);
      // The first heading of each set is the tell for which one is showing.
      expect(find.text('ACTIVITIES'), findsOneWidget);
      expect(find.text('SMILEYS & EMOTION'), findsNothing);

      await tester.tap(find.text('Emoji'));
      await tester.pumpAndSettle();
      expect(find.text('SMILEYS & EMOTION'), findsOneWidget);
    });

    testWidgets('search finds an emoji by its Unicode name', (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: TextButton(
              onPressed: () =>
                  showIconPicker(context, icon: '', emoji: defaultEmoji),
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();
      // Opens on Emoji, since that is what this habit wears.
      expect(find.text('SMILEYS & EMOTION'), findsOneWidget);

      await tester.tap(find.byTooltip('Search'));
      await tester.pumpAndSettle();
      // Capitalised in the data ('OK hand'), typed lowercase by the user.
      await tester.enterText(find.byType(TextField), 'ok hand');
      await tester.pumpAndSettle();

      expect(find.text('👌'), findsOneWidget);
      expect(find.text('SMILEYS & EMOTION'), findsNothing);
    });

    testWidgets('returns an icon choice, not an emoji one', (tester) async {
      IconChoice? got;
      await tester.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: TextButton(
              onPressed: () async => got = await showIconPicker(context,
                  icon: defaultIcon, emoji: ''),
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();

      await tester.tap(find.byIcon(iconByKey['phone']!));
      await tester.pumpAndSettle();

      expect(got?.icon, 'phone');
      expect(got?.emoji, '');
    });
  });
}
